from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(2, 8))
    vals = draw(st.lists(
        st.one_of(st.integers(1, 20), st.integers(1, 10**9)),
        min_size=n, max_size=n))
    vals.sort()
    if draw(st.booleans()):
        # force some duplicates / all-equal cases
        v = draw(st.integers(1, 20))
        k = draw(st.integers(0, n))
        vals = sorted([v] * k + vals[k:])[:n]
    return f"{n}\n{' '.join(map(str, vals))}\n"


def validate(inp):
    try:
        t = inp.split()
        n = int(t[0])
        a = [int(x) for x in t[1:]]
    except Exception:
        return False
    if not (2 <= n <= 5 * 10**5):
        return False
    if len(a) != n:
        return False
    if not all(1 <= x <= 10**9 for x in a):
        return False
    if any(a[i] > a[i + 1] for i in range(n - 1)):
        return False
    return True


def ref(inp):
    from functools import lru_cache
    t = inp.split()
    n = int(t[0])
    a = [int(x) for x in t[1:1 + n]]

    def can_pair(i, j):
        # i and j can form a kagamimochi in either orientation
        return 2 * a[i] <= a[j] or 2 * a[j] <= a[i]

    @lru_cache(maxsize=None)
    def f(mask):
        if mask == 0:
            return 0
        i = (mask & -mask).bit_length() - 1
        rest = mask & ~(1 << i)
        best = f(rest)  # element i is not used in any pair
        for j in range(n):
            if (rest >> j) & 1 and can_pair(i, j):
                best = max(best, 1 + f(rest & ~(1 << j)))
        return best

    return str(f((1 << n) - 1))
